INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_jeep_wj_blend_door_5012710aa',
  'part_jeep_wj_blend_door_5012710aa',
  '[{"name":"8mm Low-Profile Ratchet Wrench","purpose":"Extract blind rear actuator mounting fasteners behind dashboard sub-frame","amazon_search_keyword":"8mm low profile ratchet wrench"},{"name":"T15 Torx Screwdriver","purpose":"Remove glove box damper hinge and lower trim screws","amazon_search_keyword":"T15 torx screwdriver long shank"},{"name":"Automotive Synthetic Silicone Grease","purpose":"Lubricate internal drive gear teeth and housing pivot post","amazon_search_keyword":"synthetic automotive gear grease"}]',
  'Moderate',
  '45 mins',
  '[{"step_number":1,"title":"Glove Box Drop and Airbox Visual Access","text":"Open the glove compartment door, press inward on the plastic stops on both left and right sides to disengage the travel limiters, and rotate the door completely downward. Locate the passenger-side blend door actuator mounted directly to the HVAC housing sub-frame.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid1\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid1)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: 5012710AA - GLOVE BOX CARRIER RELEASE</text><rect x=\"220\" y=\"120\" width=\"360\" height=\"220\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><path d=\"M 260 120 L 260 280 L 540 280\" stroke=\"#38bdf8\" stroke-width=\"1.5\" fill=\"none\"/><circle cx=\"240\" cy=\"150\" r=\"8\" fill=\"#f59e0b\"/><circle cx=\"560\" cy=\"150\" r=\"8\" fill=\"#f59e0b\"/><path d=\"M 200 150 L 230 150\" stroke=\"#4ade80\" stroke-width=\"3\" marker-end=\"arrow\"/><path d=\"M 600 150 L 570 150\" stroke=\"#4ade80\" stroke-width=\"3\"/><path d=\"M 400 280 L 400 350\" stroke=\"#4ade80\" stroke-width=\"3\" stroke-dasharray=\"4\"/></svg>"},{"step_number":2,"title":"Actuator Fastener Removal and Harness Disconnect","text":"Disconnect the 2-pin electrical connector by depressing the central tab. Use an 8mm low-profile ratchet wrench to back out the two retaining hex head bolts securing the actuator bracket to the airbox. Carefully lower the assembly straight down to clear the D-shaped door drive shaft.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid2\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid2)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: 5012710AA - ACTUATOR UNBOLT & HARNESS SEPARATION</text><rect x=\"280\" y=\"140\" width=\"240\" height=\"180\" rx=\"8\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"310\" cy=\"165\" r=\"6\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"490\" cy=\"295\" r=\"6\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 400 140 L 400 100\" stroke=\"#4ade80\" stroke-width=\"3\"/><rect x=\"370\" y=\"80\" width=\"60\" height=\"20\" fill=\"#f59e0b\"/></svg>"},{"step_number":3,"title":"Clamshell Separation and Cracked POM Gear Extraction","text":"Insert a precision flat blade into the four perimeter plastic locking clips along the seam of the actuator housing. Separate the top case to expose the reduction gear train. Extract the large split drive gear from the metal motor worm gear spindle, noting the internal shaft key orientation.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid3\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid3)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: 5012710AA - CLAMSHELL PRY & BROKEN GEAR EXTRACTION</text><circle cx=\"400\" cy=\"225\" r=\"70\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"4\" fill=\"rgba(6, 182, 212, 0.12)\"/><line x1=\"400\" y1=\"155\" x2=\"400\" y2=\"225\" stroke=\"#ef4444\" stroke-width=\"3\"/><path d=\"M 360 180 L 320 140\" stroke=\"#f59e0b\" stroke-width=\"3\"/><path d=\"M 400 225 L 400 120\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"PA12 Replacement Gear Press-Fit and Re-indexing","text":"Apply synthetic gear grease to the gear teeth. Align the Barebones 3D PA12 replacement gear bore onto the center metal drive post. Press the gear firmly into mesh with the intermediate drive pinions. Snap the clamshell cover shut until all tabs click, reinstall the actuator with the 8mm bolts, and perform the WJ dual-zone climate calibration sequence.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid4\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid4)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: 5012710AA - NYLON GEAR PRESS-FIT & SYNCHRONIZATION</text><circle cx=\"400\" cy=\"225\" r=\"70\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"225\" r=\"20\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 400 100 L 400 150\" stroke=\"#4ade80\" stroke-width=\"4\"/><path d=\"M 385 135 L 400 150 L 415 135\" fill=\"none\" stroke=\"#4ade80\" stroke-width=\"4\"/></svg>"}]',
  '[{"question":"Why did the original gear split in half?","answer":"The factory Chrysler gear is molded from unfilled polyoxymethylene (POM). Constant engine bay thermal cycling embrittles the plastic, while motor stall-torque at travel endpoints induces hoop-stress fractures at the hub."},{"question":"How do I run the HVAC diagnostic calibration on the WJ?","answer":"Turn the ignition ON. Set both driver and passenger temp knobs to 75°F. Simultaneously press and hold the ''A/C'' and ''Recirc'' buttons while turning the left temperature control knob one click clockwise. Release both buttons."}]'
);

