INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_ford_f150_blend_door_dl3z_19e616_a',
  'part_ford_f150_blend_door_dl3z_19e616_a',
  '[{"name":"5.5mm (7/32\") Nut Driver & Flex Socket","purpose":"Remove the microscopic factory Ford actuator mounting screws behind dash cavity","amazon_search_keyword":"5.5mm flex head socket 1/4 drive"},{"name":"Non-Marring Trim Tool","purpose":"Pry dash decorative trim panels without marring vinyl grain","amazon_search_keyword":"automotive non marring trim pry tool kit"},{"name":"8mm Magnetic Socket","purpose":"Remove center console side bracket anchor bolts","amazon_search_keyword":"8mm magnetic socket 1/4 drive"}]',
  'Moderate',
  '50 mins',
  '[{"step_number":1,"title":"Center Stack Side Trim Release","text":"Insert a non-marring pry bar into the lower seam of the center console trim panel on the passenger side. Pop the metal spring clips outward to reveal the lower HVAC plenum casing. Disconnect the auxiliary 12V socket harness.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid5\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid5)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: DL3Z-19E616-A - DASH BEZEL PRY & ACCESS</text><path d=\"M 300 100 L 450 100 L 520 350 L 300 350 Z\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><path d=\"M 520 220 L 580 200\" stroke=\"#f59e0b\" stroke-width=\"4\"/><path d=\"M 510 210 L 470 210\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Actuator Extraction (5.5mm Fasteners)","text":"Use a 5.5mm (7/32\") flex socket to remove the two rear-facing screws holding the blend door actuator to the air distribution box. Clear the wiring loom clip from the actuator housing, unplug the electrical connector, and draw the unit down.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid6\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid6)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: DL3Z-19E616-A - 5.5MM SCREW UNSEATING</text><rect x=\"260\" y=\"140\" width=\"280\" height=\"180\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"290\" cy=\"170\" r=\"8\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"510\" cy=\"290\" r=\"8\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 400 230 L 400 350\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":3,"title":"Housing Tab Release and Stripped Gear Removal","text":"Disengage the five perimeter locking tabs of the black plastic housing using a small flathead tool. Pry open the case. Pull the large output reduction gear off its metal axle pin. Observe the missing or sheared teeth that caused the classic Ford dashboard clicking sound.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid7\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid7)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: DL3Z-19E616-A - GEAR TEETH INSPECTION</text><circle cx=\"400\" cy=\"225\" r=\"80\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><rect x=\"390\" y=\"145\" width=\"20\" height=\"20\" fill=\"#ef4444\"/><path d=\"M 400 130 L 400 90\" stroke=\"#4ade80\" stroke-width=\"3\"/><path d=\"M 480 225 L 530 225\" stroke=\"#f59e0b\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"PA12 Splined Gear Drop-In and HVAC Relearn","text":"Seat the Barebones 3D PA12 replacement reduction gear onto the center steel axle. Re-mesh with the intermediate worm pinion, verifying clean concentric rotation. Snap the top case shut, rebolt with the 5.5mm fasteners, pull the HVAC fuse in the passenger kick panel for 60 seconds, and cycle ignition ON to initiate auto-calibration.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid8\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid8)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: DL3Z-19E616-A - PA12 INSTALL & MODULE RELEARN</text><circle cx=\"400\" cy=\"225\" r=\"80\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"225\" r=\"24\" fill=\"#4ade80\"/><path d=\"M 320 225 A 80 80 0 0 1 480 225\" stroke=\"#4ade80\" stroke-width=\"3\" stroke-dasharray=\"4\"/></svg>"}]',
  '[{"question":"What causes the rapid clicking sound behind my F-150 radio?","answer":"When the HVAC door reaches physical travel limits, the motor continues to supply torque. The weak factory POM gear teeth shear off, causing the worm gear to skip rapidly across the stripped void."},{"question":"Do I have to remove the entire dash to fix this?","answer":"No. Dealership flat rate pays for complete dashboard drop, but with a 5.5mm flex-head ratchet, this sub-gear replacement can be completed through the passenger glovebox cavity in under an hour."}]'
);

