INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_bose_qc35_hinge_assy',
  'part_bose_qc35_hinge_assy',
  '[{"name":"PH00 Precision Phillips Screwdriver","purpose":"Back out internal micro-screws securing inner headphone pivot covers","amazon_search_keyword":"PH00 precision screwdriver"},{"name":"Nylon Spudger Pry Tool","purpose":"Unsnap headband trim rings without marring the finish","amazon_search_keyword":"electronics nylon spudger pry tool"},{"name":"Fine Curved Tweezers","purpose":"Route ultra-thin audio wires through the replacement hinge tunnel","amazon_search_keyword":"curved precision tweezers ESD"}]',
  'Easy',
  '25 mins',
  '[{"step_number":1,"title":"Ear Pad and Inner Dust Scrim Removal","text":"Grip the edge of the leatherette ear cushion and pull firmly inward to disengage the eight perimeter plastic locking tabs. Peel back the foam inner scrim to inspect the swivel joint wiring channel.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid9\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid9)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: QC35 - CUSHION RELEASE & WIRE EXPOSURE</text><ellipse cx=\"400\" cy=\"225\" rx=\"110\" ry=\"140\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><ellipse cx=\"400\" cy=\"225\" rx=\"70\" ry=\"90\" stroke=\"#38bdf8\" stroke-dasharray=\"4\" fill=\"none\"/><path d=\"M 400 80 L 400 40\" stroke=\"#4ade80\" stroke-width=\"3\"/><path d=\"M 510 225 L 560 225\" stroke=\"#f59e0b\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Headband Swivel Bracket Screws Extraction","text":"Locate the two PH00 screws securing the plastic interior hinge cover plate. Back them out with your precision driver and set them on a magnetic mat. Pry the cosmetic outer shell free with a spudger.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid10\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid10)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: QC35 - PH00 COVER SCREW REMOVAL</text><path d=\"M 320 160 L 480 160 L 450 300 L 350 300 Z\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"360\" cy=\"200\" r=\"5\" fill=\"#f59e0b\"/><circle cx=\"440\" cy=\"200\" r=\"5\" fill=\"#f59e0b\"/><path d=\"M 360 200 L 360 260\" stroke=\"#4ade80\" stroke-width=\"2\"/></svg>"},{"step_number":3,"title":"Broken Swivel Arm Demounting and Wiring Clearance","text":"Carefully tilt the cracked hinge collar off the steel headband slider pin. Slide the delicate audio cable through the hinge slot with tweezers. Take care not to pinch the braided shield or pull solder joints loose from the ear-cup driver board.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid11\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid11)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: QC35 - CRACKED HINGE REMOVAL & HARNESS PASS-THRU</text><rect x=\"350\" y=\"150\" width=\"100\" height=\"120\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><line x1=\"350\" y1=\"190\" x2=\"450\" y2=\"190\" stroke=\"#ef4444\" stroke-width=\"3\"/><path d=\"M 400 120 C 420 180 380 220 400 280\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/></svg>"},{"step_number":4,"title":"PA12 Replacement Hinge Seat and Mechanical Closure","text":"Thread the audio harness through the open slot of the Barebones 3D PA12 replacement swivel arm. Snap the arm over the metal pivot pin, align the cosmetic backplate, and torque the two PH00 screws until snug. Re-clip the ear cushions until you hear the eight distinct clicks.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid12\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid12)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: QC35 - PA12 SWIVEL SEATING & FASTENING</text><rect x=\"350\" y=\"150\" width=\"100\" height=\"120\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"210\" r=\"10\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 400 270 L 400 320\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"}]',
  '[{"question":"Will Bose repair just the plastic hinge collar?","answer":"No. Bose considers the hinge non-serviceable and will only offer an out-of-warranty replacement unit for $150 to $200+, rendering this $19 repair an 88% cost savings."},{"question":"Why is Nylon PA12 necessary instead of PLA or resin?","answer":"The swivel hinge undergoes continuous torsional twisting and tension every time the headphones are flexed onto the listener''s head. PLA creeps and fractures along layer lines, while SLS Nylon PA12 provides isotropic mechanical strength."}]'
);

