INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_dewalt_miter_saw_chute_n447388',
  'part_dewalt_miter_saw_chute_n447388',
  '[{"name":"T25 Torx Driver","purpose":"Remove the OEM rubber chute retaining screws on saw blade casting","amazon_search_keyword":"T25 torx driver heavy duty"},{"name":"Shop Vacuum with Utility Brush","purpose":"Clean out packed wood chips and resin from aluminum blade housing channel","amazon_search_keyword":"shop vac micro cleaning kit"}]',
  'Easy',
  '15 mins',
  '[{"step_number":1,"title":"Blade Guard Retraction and OEM Rubber Flap Removal","text":"Disconnect power to the miter saw. Raise the saw head to maximum height and lock the bevel angle at 0°. Locate the two T25 Torx screws securing the factory stock black rubber dust funnel behind the blade guard casting and extract them.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid13\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid13)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: N447388 - STOCK CHUTE REMOVAL</text><path d=\"M 260 120 L 520 120 L 460 320 L 320 320 Z\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"340\" cy=\"150\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"440\" cy=\"150\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 390 280 L 390 350\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Casting Channel Debris Clearance","text":"Vacuum out all packed sawdust and sticky pitch buildup along the miter saw intake manifold. Ensure the seating face of the aluminum casting is flat so the replacement chute seals flush against negative vacuum pressure.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid14\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid14)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: N447388 - SEATING FLANGE DE-BURRING</text><rect x=\"300\" y=\"160\" width=\"200\" height=\"120\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><line x1=\"280\" y1=\"220\" x2=\"520\" y2=\"220\" stroke=\"#4ade80\" stroke-width=\"2\" stroke-dasharray=\"4\"/><circle cx=\"390\" cy=\"220\" r=\"20\" fill=\"#f59e0b\"/></svg>"},{"step_number":3,"title":"Aerodynamic PETG Deflector Chute Positioning","text":"Slide the Barebones 3D PETG chute down over the saw arm neck. The dual contoured intake scoops must drop directly behind the kerf line of the 12-inch blade without making contact with the moving blade guard linkage.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid15\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid15)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: N447388 - PETG CHUTE ALIGNMENT & FIT</text><path d=\"M 320 140 L 480 140 L 440 300 L 360 300 Z\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"330\" r=\"30\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"4\" fill=\"none\"/><path d=\"M 400 90 L 400 130\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"Fastener Re-Torque and Bevel Clearance Validation","text":"Re-install the two factory T25 Torx screws through the chute''s reinforced mounting eyelets. Hand tighten securely without stripping into the aluminum threads. Slowly pivot the saw through its entire 47° left and right bevel sweep to confirm zero collision.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid16\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid16)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: N447388 - FULL ARTICULATION CLEARANCE CHECK</text><path d=\"M 250 300 A 180 180 0 0 1 550 300\" stroke=\"#4ade80\" stroke-width=\"3\" stroke-dasharray=\"6\" fill=\"none\"/><line x1=\"400\" y1=\"300\" x2=\"400\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"3\"/><circle cx=\"400\" cy=\"300\" r=\"10\" fill=\"#f59e0b\"/></svg>"}]',
  '[{"question":"Why does the factory DeWalt dust chute perform so poorly?","answer":"The stock rubber chute sits over 3 inches back from the blade kerf and flexes away under suction, catching less than 40% of waste stream particles. This rigid, contoured scoop captures upward of 90%."},{"question":"Will this part melt from blade friction or hot carbide teeth?","answer":"No. The chute is printed in industrial PETG with a 75°C+ heat deflection temperature and is engineered with clearance to maintain an intentional 8mm air gap away from high-speed carbide tooth orbit."}]'
);

