INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_technics_sl1200_hinge_sfumm02n04',
  'part_technics_sl1200_hinge_sfumm02n04',
  '[{"name":"JIS #2 Screwdriver (or PH2)","purpose":"Back out chassis hinge pocket screws without stripping Japanese Industrial Standard heads","amazon_search_keyword":"Vessel JIS screwdriver #2"},{"name":"Needle-Nose Pliers","purpose":"Retain and seat the heavy internal steel hinge torsion spring","amazon_search_keyword":"mini needle nose pliers smooth jaw"}]',
  'Easy',
  '20 mins',
  '[{"step_number":1,"title":"Dust Cover Separation and Remnant Removal","text":"Lift the acrylic dust cover vertically off the chassis. Back out the two JIS #2 screws securing the broken die-cast/plastic lower hinge receiver bracket from the rear aluminum plinth.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid17\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid17)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: SFUMM02N04 - DUST COVER DETACHMENT</text><rect x=\"220\" y=\"140\" width=\"360\" height=\"180\" rx=\"4\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"260\" cy=\"300\" r=\"8\" fill=\"#f59e0b\"/><circle cx=\"540\" cy=\"300\" r=\"8\" fill=\"#f59e0b\"/><path d=\"M 400 140 L 400 80\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Torsion Spring Pin Transfer","text":"Use needle-nose pliers to extract the internal steel pivot pin and spring from the damaged original housing. Inspect the spring tangs for corrosion or fatigue bending, and wipe clean.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid18\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid18)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: SFUMM02N04 - TORSION SPRING TRANSFER</text><rect x=\"330\" y=\"150\" width=\"140\" height=\"150\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"400\" cy=\"225\" r=\"25\" stroke=\"#f59e0b\" stroke-width=\"3\" stroke-dasharray=\"4\" fill=\"none\"/><path d=\"M 400 200 L 440 160\" stroke=\"#f59e0b\" stroke-width=\"3\"/></svg>"},{"step_number":3,"title":"ASA Bracket Base Installation","text":"Position the Barebones 3D UV-resistant ASA replacement hinge bracket into the rear plinth recess. Secure the base using the factory metric M3/M4 JIS screws, making sure the mount is seated squarely against the plinth.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid19\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid19)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: SFUMM02N04 - ASA BRACKET SEATING</text><rect x=\"330\" y=\"150\" width=\"140\" height=\"150\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"360\" cy=\"270\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"440\" cy=\"270\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 400 110 L 400 150\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"Acrylic Cover Insertion and Hinge Tension Check","text":"Load the steel torsion spring into the ASA bracket socket and insert the hinge slide tab. Slide the acrylic dust cover tongue straight down into the receiver until it seats. Test open/close holding tension at a 45-degree angle.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid20\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid20)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: SFUMM02N04 - TENSION & COVER DOCKING</text><path d=\"M 260 200 L 420 120 L 520 280\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"none\"/><path d=\"M 340 180 A 60 60 0 0 1 400 240\" stroke=\"#4ade80\" stroke-width=\"2\" stroke-dasharray=\"4\" fill=\"none\"/></svg>"}]',
  '[{"question":"Why did Panasonic discontinue this part?","answer":"Panasonic phased out legacy SL-1200MK2 component spares in the early 2010s. OEM new-old-stock pairs now trade on vintage Hi-Fi marketplaces for over $100."},{"question":"Why is ASA used instead of standard black ABS?","answer":"Automotive ASA delivers the high impact strength of ABS but contains an acrylate elastomer that provides total immunity to UV yellowing and solar degradation from room sunlight."}]'
);

