INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_subaru_visor_clip_92011sc022lo',
  'part_subaru_visor_clip_92011sc022lo',
  '[{"name":"Flathead Pocket Screwdriver","purpose":"Pop open the cosmetic screw concealment cap","amazon_search_keyword":"precision flathead pocket screwdriver"},{"name":"T20 Torx Bit Driver","purpose":"Remove the factory anchor screw into headliner sheet metal","amazon_search_keyword":"T20 torx screwdriver automotive"}]',
  'Beginner',
  '10 mins',
  '[{"step_number":1,"title":"Cosmetic Hinge Cap Pry","text":"Insert a thin flathead screwdriver into the small notch on the underside of the visor pivot base. Pop open the plastic hinged cover to expose the mounting screw.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid21\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid21)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: 92011SC022LO - CONCEALMENT CAP RELEASE</text><ellipse cx=\"400\" cy=\"225\" rx=\"100\" ry=\"70\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><path d=\"M 480 235 L 530 250\" stroke=\"#f59e0b\" stroke-width=\"3\"/><path d=\"M 400 225 L 400 170\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"T20 Fastener Extraction and Clip Drop","text":"Back out the single T20 Torx screw securing the bracket to the roof crossmember. Rotate the broken visor clip 90 degrees counter-clockwise to release the internal retention ears from the sheet metal slot.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid22\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid22)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: 92011SC022LO - T20 BOLT & ROOF KEYWAY RELEASE</text><circle cx=\"400\" cy=\"225\" r=\"50\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"400\" cy=\"225\" r=\"8\" fill=\"#f59e0b\"/><path d=\"M 400 225 A 35 35 0 0 1 450 200\" stroke=\"#4ade80\" stroke-width=\"3\" fill=\"none\"/></svg>"},{"step_number":3,"title":"ASA High-Temp Replacement Block Insertion","text":"Slide the Barebones 3D ASA visor anchor block into the keyed roof opening. Rotate 90 degrees clockwise until the retention shoulders lock behind the sheet metal backing.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid23\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid23)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: 92011SC022LO - ASA REPLACEMENT ENGAGEMENT</text><circle cx=\"400\" cy=\"225\" r=\"50\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><path d=\"M 400 130 L 400 180\" stroke=\"#4ade80\" stroke-width=\"4\"/></svg>"},{"step_number":4,"title":"Torque Fastener and Snap Engagement Test","text":"Thread the factory T20 screw through the counterbore hole and tighten securely. Fold the visor stalk in and out of the clip jaw to verify positive mechanical retention without binding.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid24\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid24)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: 92011SC022LO - RETENTION JAW CALIBRATION</text><rect x=\"350\" y=\"180\" width=\"100\" height=\"90\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"400\" cy=\"225\" r=\"16\" fill=\"#4ade80\"/><path d=\"M 320 225 L 360 225\" stroke=\"#f59e0b\" stroke-width=\"3\"/></svg>"}]',
  '[{"question":"Why do Subaru visor clips snap constantly?","answer":"Subaru''s OEM plastic contains zero UV stabilizers. Sitting directly behind the windshield greenhouse generates interior cabin soak temperatures above 65°C, causing the plastic jaw tabs to snap on simple visor pulls."},{"question":"Can this be printed in PLA?","answer":"Never use PLA inside an automobile cabin. PLA softens at 55°C (131°F) and will deform within 48 hours of summer parking. Automotive ASA maintains dimensional stability past 95°C."}]'
);

-- Part: Ford F-150 / Super Duty Vista Sunroof Track Slider Lift Arm (OEM #FL3Z-16502C22-E)
