INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_ford_sunroof_arm_fl3z_16502c22_e',
  'part_ford_sunroof_arm_fl3z_16502c22_e',
  '[{"name":"T25 Torx Driver","purpose":"Extract the six glass sunroof panel retaining shoulder bolts","amazon_search_keyword":"T25 torx driver long reach"},{"name":"Plastic Trim Bone Tool","purpose":"Unclip flexible rubber accordion debris bellows","amazon_search_keyword":"automotive trim bone tool"},{"name":"Krytox GPL 205 Fluorinated Synthetic Grease","purpose":"Lubricate sliding guide channels with OEM specified grease","amazon_search_keyword":"krytox gpl 205 grease syringe"}]',
  'Advanced',
  '90 mins',
  '[{"step_number":1,"title":"Bellows Detachment and Moving Glass Removal","text":"Place the sunroof in the vent position. From inside the cabin, gently pull the rubber side accordion bellows inward to release them from the lower track channel. Use a T25 Torx driver to remove the three retaining bolts on each side of the glass panel. Carefully lift the sunroof glass up and out of the vehicle.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid25\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid25)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: FL3Z-16502C22-E - GLASS EXTRACTION</text><rect x=\"240\" y=\"140\" width=\"320\" height=\"160\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"270\" cy=\"170\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"270\" cy=\"220\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"270\" cy=\"270\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 400 140 L 400 70\" stroke=\"#4ade80\" stroke-width=\"4\"/></svg>"},{"step_number":2,"title":"Broken Lift Arm Fragment Extraction","text":"Locate the fractured glass lift arm inside the aluminum extrusion rail. Cycle the sunroof motor slightly if necessary to draw the drive cable slider into view. Extract the broken rear cam slider fragments and vacuum the aluminum channel clean of plastic debris.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid26\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid26)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: FL3Z-16502C22-E - TRACK CLEARANCE & FRAGMENT DEBRIS</text><line x1=\"200\" y1=\"225\" x2=\"600\" y2=\"225\" stroke=\"#38bdf8\" stroke-width=\"4\"/><rect x=\"360\" y=\"205\" width=\"80\" height=\"40\" stroke=\"#ef4444\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 400 205 L 400 150\" stroke=\"#4ade80\" stroke-width=\"3\"/><circle cx=\"400\" cy=\"225\" r=\"4\" fill=\"#f59e0b\"/></svg>"},{"step_number":3,"title":"PA12 Billet Slider Seating and Cable Pin Engagement","text":"Coat the track slides with Krytox grease. Align the Barebones 3D reinforced Nylon PA12 lift arm into the track slot. Guide the drive cable steel drive lug directly into the slider''s reinforced pivot pocket until fully engaged.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid27\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid27)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: FL3Z-16502C22-E - PA12 SLIDER DOCKING & LUBRICATION</text><path d=\"M 300 240 L 440 180 L 500 240 Z\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"370\" cy=\"220\" r=\"8\" fill=\"#f59e0b\"/><path d=\"M 300 240 L 250 240\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"Glass Re-Installation and Sunroof Module Initialization","text":"Carefully lower the glass back into place and finger-tighten the six T25 Torx screws. Align glass gaps flush with roof sheet metal, then torque to 4.5 Nm. Perform the Ford sunroof initialization: press and hold the TILT button until the sunroof completes a full down-tilt-slide cycle.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid28\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid28)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: FL3Z-16502C22-E - GLASS FLUSH GAP & INITIALIZATION</text><line x1=\"220\" y1=\"200\" x2=\"580\" y2=\"200\" stroke=\"#38bdf8\" stroke-width=\"4\"/><rect x=\"260\" y=\"190\" width=\"280\" height=\"20\" fill=\"rgba(6, 182, 212, 0.2)\"/><path d=\"M 400 170 L 400 230\" stroke=\"#4ade80\" stroke-width=\"3\" stroke-dasharray=\"4\"/></svg>"}]',
  '[{"question":"What is the dealer gouge on this sunroof failure?","answer":"Ford refuses to sell individual replacement plastic track arms. Dealerships require purchasing the entire panoramic frame cassette (OEM FL3Z-16502C22-E) for $1,800 to $2,400, plus 6 to 8 hours of labor dropping the headliner."},{"question":"How does Barebones 3D prevent this from snapping again?","answer":"The factory parts are molded from brittle unfilled PBT with thin wall cross-sections. Our replacement is engineered from solid Nylon PA12 with increased gusset thickness at the high-shear cable guide pin pocket."}]'
);

-- Part: GM GMT900 HVAC Recirculation & Defrost Blend Door Actuator Cam Lever (OEM #20826188)
