  id, slug, title, oem_part_number, superseded_numbers, compatible_makes_models,
  material_spec, retail_price_cents, stl_r2_key, original_source_url,
  license_type, attribution_text, is_commercial_allowed, is_active, status
) VALUES (
  'part_gm_gmt900_blend_cam_20826188',
  'gm-gmt900-hvac-recirculation-defrost-blend-door-actuator-cam-lever-20826188',
  'GM GMT900 HVAC Recirculation & Defrost Blend Door Actuator Cam Lever',
  '20826188',
  '["15-73952","15844066","25884454"]',
  '[{"make":"Chevrolet","model":"Silverado 1500/2500","year_start":2007,"year_end":2014},{"make":"GMC","model":"Sierra","year_start":2007,"year_end":2014},{"make":"Chevrolet","model":"Tahoe / Suburban","year_start":2007,"year_end":2014},{"make":"GMC","model":"Yukon","year_start":2007,"year_end":2014}]',
