INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_gm_gmt900_blend_cam_20826188',
  'part_gm_gmt900_blend_cam_20826188',
  '[{"name":"5.5mm (7/32\") Flex-Head Micro-Ratchet","purpose":"Access the recessed blind mounting screws securing the actuator above the gas pedal","amazon_search_keyword":"micro ratchet 5.5mm flex head"},{"name":"7mm Nut Driver","purpose":"Drop the lower dashboard knee bolster and steering column trim","amazon_search_keyword":"7mm nut driver magnetic automotive"},{"name":"Straight Mechanic Pick","purpose":"Manipulate flapper door pivot to verify smooth free-hang rotation","amazon_search_keyword":"automotive pick set mechanic"}]',
  'Moderate',
  '60 mins',
  '[{"step_number":1,"title":"Knee Bolster Drop and Duct Clearance","text":"Remove the four 7mm hex screws securing the driver-side lower dash knee bolster trim panel. Pop the metal spring clips free and set the bolster aside. Unhook the lower footwell floor air discharge duct to reveal the HVAC case side.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid29\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid29)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: 20826188 - KNEE BOLSTER & DUCT DISASSEMBLY</text><rect x=\"240\" y=\"120\" width=\"320\" height=\"200\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"270\" cy=\"150\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"530\" cy=\"150\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"270\" cy=\"290\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 400 320 L 400 380\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Actuator Extraction and Blind Fastener Access","text":"Unplug the electrical connector from the defrost/mode actuator. Using a 5.5mm flex micro-ratchet, remove the two mounting screws. Pull the actuator straight off the airbox flapper shaft.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid30\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid30)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: 20826188 - ACTUATOR UNBOLTING (5.5MM)</text><rect x=\"300\" y=\"150\" width=\"200\" height=\"160\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"330\" cy=\"180\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"470\" cy=\"280\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 400 230 L 400 340\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":3,"title":"Sheared Cam Lever Extraction","text":"Inspect the output drive. The original white POM cam lever cracks across the splined hub keyway, spinning freely on the shaft. Pull the broken cam off the airbox flapper door shaft with pliers and clean the splined pin.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid31\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid31)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: 20826188 - SHEARED CAM HUB SPLINE REMOVAL</text><path d=\"M 340 240 C 340 180 460 180 460 240 Z\" stroke=\"#ef4444\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"400\" cy=\"220\" r=\"12\" fill=\"#f59e0b\"/><line x1=\"400\" y1=\"208\" x2=\"400\" y2=\"180\" stroke=\"#ef4444\" stroke-width=\"3\"/><path d=\"M 450 210 L 500 210\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"PA12 Cam Installation and GM Auto-Calibration","text":"Press the Barebones 3D PA12 splined cam lever onto the flapper shaft until seated against the shoulder stop. Align the cam track pin with the actuator guide slot. Bolt the actuator down, reconnect the harness, pull the HVAC/ECU B fuse for 1 minute, and turn the key ON for a 90-second automated recalibration sweep.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid32\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid32)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: 20826188 - REINFORCED CAM INSTALL & RELEARN</text><path d=\"M 340 240 C 340 170 460 170 460 240 Z\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"215\" r=\"14\" fill=\"#4ade80\"/><path d=\"M 400 130 L 400 180\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"}]',
  '[{"question":"Why does air stay stuck blowing only out of the dashboard defrost vents?","answer":"GM''s default safety fail-position for the GMT900 HVAC distribution case is full windshield defrost. When the plastic cam lever snaps, spring tension defaults the air door to the windshield."},{"question":"What is the dealer quote for this repair?","answer":"GM dealer technicians frequently claim the entire air distribution case must be replaced when the internal cam shears, quoting $1,200 to $1,600 involving complete instrument panel removal."}]'
);

-- Part: Whirlpool Dishwasher Lower Dishrack Roller Wheel & Axle Clip (OEM #WPW10195417)
INSERT OR REPLACE INTO parts (
  id, slug, title, oem_part_number, superseded_numbers, compatible_makes_models,
  material_spec, retail_price_cents, stl_r2_key, original_source_url,
  license_type, attribution_text, is_commercial_allowed, is_active, status
) VALUES (
  'part_whirlpool_dishrack_wheel_wpw10195417',
  'whirlpool-dishwasher-lower-dishrack-roller-wheel-axle-clip-wpw10195417',
  'Whirlpool Dishwasher Lower Dishrack Roller Wheel & Axle Clip',
  'WPW10195417',
  '["W10195417","8539324","W10195416V","1548679"]',
  '[{"make":"Whirlpool","model":"Quiet Partner series"},{"make":"KitchenAid","model":"KDFE / KDTE dishwashers"},{"make":"Kenmore","model":"Elite 665 series"},{"make":"Maytag","model":"MDB series"}]',
  'PETG Heavy Duty',
  0,
  'parts/whirlpool-dishwasher-lower-dishrack-roller-wheel-axle-clip-wpw10195417.stl',
