INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_whirlpool_dishrack_wheel_wpw10195417',
  'part_whirlpool_dishrack_wheel_wpw10195417',
  '[{"name":"Flat Blade Pocket Screwdriver","purpose":"Depress the center snap barb on the brittle wire retention clip","amazon_search_keyword":"flathead pocket screwdriver"}]',
  'Beginner',
  '5 mins',
  '[{"step_number":1,"title":"Dishtray Extraction and Wheel Inspection","text":"Pull the lower dishrack completely out of the wash tub and place it inverted on a clean counter. Inspect the eight roller positions to locate melted, flat-spotted, or missing wheels.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid33\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid33)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: WPW10195417 - LOWER RACK DISMOUNT & INSPECTION</text><rect x=\"220\" y=\"150\" width=\"360\" height=\"160\" rx=\"6\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"260\" cy=\"310\" r=\"16\" fill=\"#f59e0b\"/><circle cx=\"540\" cy=\"310\" r=\"16\" fill=\"#f59e0b\"/><path d=\"M 400 150 L 400 90\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Damaged Wheel Clip Separation","text":"Insert the flathead screwdriver blade beneath the central locking tang of the plastic wheel axle bracket. Pry slightly outward while pushing the wheel assembly off the steel wire frame.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid34\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid34)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: WPW10195417 - AXLE LOCKING BARB RELEASE</text><circle cx=\"400\" cy=\"225\" r=\"50\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><line x1=\"300\" y1=\"225\" x2=\"500\" y2=\"225\" stroke=\"#38bdf8\" stroke-width=\"4\"/><path d=\"M 400 225 L 450 180\" stroke=\"#f59e0b\" stroke-width=\"3\"/><path d=\"M 400 225 L 400 290\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":3,"title":"New Roller Alignment over Wire Frame","text":"Align the replacement wheel assembly with the dual wire rungs. The axle notch must straddle the lower wire while the upper locking clip hooks over the top stabilizing rail.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid35\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid35)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: WPW10195417 - FRAME WIRE ALIGNMENT</text><circle cx=\"400\" cy=\"225\" r=\"50\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><circle cx=\"400\" cy=\"225\" r=\"10\" fill=\"#f59e0b\"/><path d=\"M 400 130 L 400 170\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"Snap-Lock Engagement and Tub Glide Test","text":"Press inward firmly with your thumb on the wheel axle until the retention barb clicks over the wire. Return the rack to the dishwasher tub and roll it in and out to ensure smooth, unhindered tracking over the tub door bridge.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid36\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid36)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: WPW10195417 - POSITIVE LOCKING & TRACK CHECK</text><line x1=\"200\" y1=\"260\" x2=\"600\" y2=\"260\" stroke=\"#38bdf8\" stroke-width=\"3\"/><circle cx=\"350\" cy=\"240\" r=\"20\" fill=\"#4ade80\"/><circle cx=\"480\" cy=\"240\" r=\"20\" fill=\"#4ade80\"/><path d=\"M 480 240 L 540 240\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"}]',
  '[{"question":"Why is this part listed as affiliate-only instead of print-on-demand?","answer":"OEM appliance counters charge $35 per single roller wheel. However, high-grade injection-molded 8-packs are widely available on Amazon for under $12. Print-on-demand unit economics cannot compete with $1.50/wheel pricing, so we direct owners to mass-market multipacks via affiliate routing while providing free STL files for DIY makers."},{"question":"Can I print this part on my home printer?","answer":"Yes, but you must use PETG, ABS, or Nylon. PLA will soften, warp, and release micro-plastics during the dishwasher''s 65°C (150°F) heated wash and sanitize dry cycles."}]'
);

