INSERT OR REPLACE INTO guides (
  id, part_id, tools_needed, difficulty, time_estimate, steps, faq
) VALUES (
  'guide_dyson_v10_v11_trigger_970050_01',
  'part_dyson_v10_v11_trigger_970050_01',
  '[{"name":"T8 Torx Screwdriver (100mm+ Long Shaft)","purpose":"Reach deep recessed screws in Dyson handle and cyclone motor assembly","amazon_search_keyword":"long shank T8 torx screwdriver dyson"},{"name":"PH0 Precision Screwdriver","purpose":"Remove battery interface terminal screws","amazon_search_keyword":"PH0 precision screwdriver"},{"name":"Plastic Spudger","purpose":"Separate the handle clamshell without marring outer paint","amazon_search_keyword":"plastic spudger electronics repair"}]',
  'Moderate',
  '40 mins',
  '[{"step_number":1,"title":"Battery and Bin Release","text":"Press the red lever to release and slide off the clear dust bin. Unscrew the three Torx/Phillips screws securing the battery pack (one on the rear handle spine, two on the base) and drop the battery out.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid37\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid37)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 01: 970050-01 - BATTERY & CYCLONE BIN SEPARATION</text><rect x=\"260\" y=\"120\" width=\"160\" height=\"200\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><rect x=\"420\" y=\"220\" width=\"120\" height=\"100\" stroke=\"#f59e0b\" stroke-width=\"2\" fill=\"none\"/><path d=\"M 480 320 L 480 370\" stroke=\"#4ade80\" stroke-width=\"3\"/><path d=\"M 340 120 L 340 70\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":2,"title":"Motor Body Clamshell Separation","text":"Using a long-shank T8 Torx driver, extract the five perimeter screws securing the main handle halves. Disconnect the electrical wire harness leading to the LCD/trigger microswitch board and separate the housing.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid38\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid38)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 02: 970050-01 - T8 LONG-SHANK FASTENER REMOVAL</text><path d=\"M 300 140 L 480 140 L 420 320 L 320 320 Z\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.12)\"/><circle cx=\"330\" cy=\"170\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"450\" cy=\"170\" r=\"6\" fill=\"#f59e0b\"/><circle cx=\"360\" cy=\"290\" r=\"6\" fill=\"#f59e0b\"/><path d=\"M 480 220 L 530 220\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":3,"title":"Broken Trigger Lever Extraction","text":"Locate the red trigger mechanism. The common failure point is the microscopic internal plastic structural rib that contacts the electronic microswitch. Slide the broken trigger out of its retention track along with the small coil spring.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid39\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid39)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 03: 970050-01 - FRACTURED TRIGGER RIB REMOVAL</text><path d=\"M 360 200 L 420 200 L 400 280 L 370 280 Z\" stroke=\"#ef4444\" stroke-width=\"2\" fill=\"none\"/><line x1=\"380\" y1=\"200\" x2=\"380\" y2=\"160\" stroke=\"#ef4444\" stroke-width=\"3\"/><circle cx=\"420\" cy=\"240\" r=\"8\" fill=\"#f59e0b\"/><path d=\"M 420 200 L 460 170\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"},{"step_number":4,"title":"Reinforced Trigger Installation and Clamshell Assembly","text":"Position the heavy-duty reinforced trigger into the guide slot, making sure the return coil spring is seated over the guide pin. Re-align the handle clamshell, route the wiring away from pinch points, and re-torque the five T8 screws. Slide the battery pack into place and verify immediate motor response.","svg_code":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"800\" height=\"450\" fill=\"#0a0f1d\"/><defs><pattern id=\"grid40\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M 40 0 L 0 0 0 40\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.05)\" stroke-width=\"1\"/></pattern></defs><rect width=\"800\" height=\"450\" fill=\"url(#grid40)\"/><text x=\"40\" y=\"45\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">STEP 04: 970050-01 - REINFORCED TRIGGER REASSEMBLY</text><path d=\"M 360 200 L 420 200 L 400 280 L 370 280 Z\" stroke=\"#4ade80\" stroke-width=\"2\" fill=\"rgba(6, 182, 212, 0.2)\"/><rect x=\"375\" y=\"160\" width=\"10\" height=\"40\" fill=\"#4ade80\"/><path d=\"M 400 280 L 400 330\" stroke=\"#4ade80\" stroke-width=\"3\"/></svg>"}]',
  '[{"question":"What is the OEM hostage gouge on Dyson triggers?","answer":"Dyson refuses to sell the 2-gram plastic trigger switch by itself. Dyson service centers require purchasing the entire Main Body & Cyclone motor assembly for $99 to $149."},{"question":"Why monetize this part via affiliate link rather than print-on-demand?","answer":"Mass-produced injection-molded polycarbonate triggers bundled with the required deep-reach T8 Torx screwdriver sell on Amazon for under $10 with next-day shipping. Routing non-printer users to an affiliate link captures broader 24-hour cart cookies, while makers can print the open-source STL on demand."}]'
);
